svg.script:
/*  */
(function() {
  'use strict';

  var currentStep = 0;
  var isAnimating = false;
  var animTimer = null;

  // DOM Elements
  var markerA = document.getElementById('a12p21-extra-marker-a');
  var markerB = document.getElementById('a12p21-extra-marker-b');
  var impactRing = document.getElementById('a12p21-extra-impact-ring');

  var btnStep0 = document.getElementById('a12p21-extra-step-0');
  var btnStep1 = document.getElementById('a12p21-extra-step-1');
  var btnStep2 = document.getElementById('a12p21-extra-step-2');
  var btnPlay  = document.getElementById('a12p21-extra-btn-play');

  var readoutTag   = document.getElementById('a12p21-extra-readout-tag');
  var readoutText1 = document.getElementById('a12p21-extra-readout-text-1');
  var readoutText2 = document.getElementById('a12p21-extra-readout-text-2');

  // Coordinate Definitions for Steps
  // Panel A Path: x from 50 (Start) -> 192 (Aperture center) -> 335 (Outside)
  // Panel B Path: x from 50 (Start) -> 144 (Membrane Wall Contact & Stop) -> 144 (Block)
  var positionsA = [50, 192, 335];
  var positionsB = [50, 144, 144];

  var stepData = [
    {
      tag: "ETAPA 1: ORIGEM",
      tagColor: "var(--a12-ouro, var(--a12p21-extra-fluxo, #F3BE5B))",
      text1: "O marcador de fluxo encontra-se no lúmen vaginal superior em ambos os painéis, antes do plano hímenal.",
      text2: "Condição basal: trajeto pérvio e área imperfurada apresentam a mesma disposição tecidual prévia."
    },
    {
      tag: "ETAPA 2: CONTATO",
      tagColor: "var(--a12-ouro, var(--a12p21-extra-fluxo, #F3BE5B))",
      text1: "Painel A: O fluxo atinge o ostium central. Painel B: O fluxo impacta diretamente a membrana contínua.",
      text2: "No hímen imperfurado (Painel B), a ausência de óstio interrompe a progressão do marcador no ponto de contato."
    },
    {
      tag: "ETAPA 3: DESFECHO",
      tagColor: "var(--a12-verde, var(--a12p21-extra-abertura, #55B889))",
      text1: "Painel A: Passagem completa com extravasamento livre. Painel B: Obstrução mecânica total e retenção.",
      text2: "Conclusão Didática: A continuidade da membrana impede fisicamente a drenagem, estabelecendo bloqueio a montante."
    }
  ];

  function setStep(step) {
    currentStep = step;

    // Update Marker positions
    if (markerA) {
      markerA.setAttribute('transform', 'translate(' + positionsA[step] + ', 155)');
    }
    if (markerB) {
      markerB.setAttribute('transform', 'translate(' + positionsB[step] + ', 155)');
    }

    // Impact ring effect on Panel B at step 1 & 2
    if (impactRing) {
      if (step >= 1) {
        impactRing.setAttribute('opacity', '1');
        impactRing.classList.add('a12p21-extra-pulse');
      } else {
        impactRing.setAttribute('opacity', '0');
        impactRing.classList.remove('a12p21-extra-pulse');
      }
    }

    // Update button visual states
    var btnMap = [btnStep0, btnStep1, btnStep2];
    for (var i = 0; i < btnMap.length; i++) {
      if (btnMap[i]) {
        if (i === step) {
          btnMap[i].classList.add('a12p21-extra-btn-active');
          btnMap[i].setAttribute('aria-pressed', 'true');
        } else {
          btnMap[i].classList.remove('a12p21-extra-btn-active');
          btnMap[i].setAttribute('aria-pressed', 'false');
        }
      }
    }

    // Update readout text & badge
    var info = stepData[step];
    if (readoutTag) {
      readoutTag.textContent = info.tag;
      readoutTag.setAttribute('fill', info.tagColor);
    }
    if (readoutText1) readoutText1.textContent = info.text1;
    if (readoutText2) readoutText2.textContent = info.text2;

    // Update root state attribute
    var root = document.getElementById('a12p21-extra-svg');
    if (root) root.setAttribute('data-flow-state', step.toString());
  }

  function playSequence() {
    if (isAnimating) return;
    isAnimating = true;
    setStep(0);

    var seq = [1, 2];
    var idx = 0;

    animTimer = setInterval(function() {
      if (idx < seq.length) {
        setStep(seq[idx]);
        idx++;
      } else {
        clearInterval(animTimer);
        isAnimating = false;
      }
    }, 1200);
  }

  // Event Listeners setup
  function bindBtn(el, action) {
    if (!el) return;
    el.addEventListener('click', function(e) {
      e.preventDefault();
      if (isAnimating && action !== playSequence) {
        clearInterval(animTimer);
        isAnimating = false;
      }
      action();
    });
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ' || e.keyCode === 13 || e.keyCode === 32) {
        e.preventDefault();
        if (isAnimating && action !== playSequence) {
          clearInterval(animTimer);
          isAnimating = false;
        }
        action();
      }
    });
  }

  bindBtn(btnStep0, function() { setStep(0); });
  bindBtn(btnStep1, function() { setStep(1); });
  bindBtn(btnStep2, function() { setStep(2); });
  bindBtn(btnPlay,  function() { playSequence(); });

  // Initialize
  setStep(0);
})();
/*  */
